        'finances'     => '<span class="content-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><path d="M14.5 9.5c-.5-.7-1.4-1.1-2.5-1.1-1.5 0-2.5.8-2.5 1.9 0 2.9 5 1.3 5 4.1 0 1.1-1 1.9-2.5 1.9-1.1 0-2.1-.4-2.7-1.2M12 6.8v10.4"/></svg></span>',
        'guidance'     => '<span class="content-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><path d="m15.8 8.2-2.2 5.4-5.4 2.2 2.2-5.4 5.4-2.2Z"/></svg></span>',
        'interpretation'=> '<span class="content-icon"><svg viewBox="0 0 24 24"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg></span>',
        'signification' => '<span class="content-icon"><svg viewBox="0 0 24 24"><path d="m12 3 1.7 5.3H19l-4.3 3.1 1.7 5.3-4.4-3.2-4.4 3.2 1.7-5.3L5 8.3h5.3L12 3Z"/><path d="M12 19v2M4 12H2M22 12h-2"/></svg></span>',
        'description'  => '<span class="content-icon"><svg viewBox="0 0 24 24"><path d="M3 5.5c3.7-1.4 6.8-.8 9 1.2 2.2-2 5.3-2.6 9-1.2v13c-3.7-1.4-6.8-.8-9 1.2-2.2-2-5.3-2.6-9-1.2v-13Z"/><path d="M12 6.7v13"/></svg></span>',
        'affirmation'  => '<span class="content-icon"><svg viewBox="0 0 24 24"><path d="M3 6h18M3 12h18M3 18h12"/></svg></span>',
    ];

    // 0. Inject SVG icons into h2 headings
    $html = preg_replace_callback(
        '#<h2([^>]*)>(.*?)</h2>#is',
        function ($m) use ($icons) {
            $attrs = $m[1];
            $text  = $m[2];
            if (strpos($text, 'content-icon') !== false) return $m[0];
            $lower = mb_strtolower(strip_tags($text), 'UTF-8');
            $type  = '';
            if (mb_strpos($lower, 'amour') !== false)         $type = 'amour';
            elseif (mb_strpos($lower, 'travail') !== false)    $type = 'travail';
            elseif (mb_strpos($lower, 'finance') !== false)    $type = 'finances';
            elseif (mb_strpos($lower, 'guidance') !== false)   $type = 'guidance';
            elseif (mb_strpos($lower, 'interpr') !== false)    $type = 'interpretation';
            elseif (mb_strpos($lower, 'signification') !== false) $type = 'signification';
            elseif (mb_strpos($lower, 'description') !== false) $type = 'description';
            elseif (mb_strpos($lower, 'affirmation') !== false)$type = 'affirmation';
            if (!$type) return $m[0];
            return '<h2' . $attrs . '>' . $icons[$type] . '<span>' . $text . '</span></h2>';
        },
        $html
    );

    // 1. Keywords: transform h3+ul pairs into .kw-cols > .kw-col
    $html = preg_replace_callback(
        '#(<section[^>]*id="sec-mots-cles"[^>]*>)(.*?)(</section>)#is',
        function ($m) {
            $inner = $m[2];
            if (preg_match_all('#<h3>(.*?)</h3>\s*(<ul>.*?</ul>)#is', $inner, $pairs, PREG_SET_ORDER)) {
                $cols = '';
                foreach ($pairs as $p) {
                    $cols .= '<div class="kw-col"><h3>' . $p[1] . '</h3>' . $p[2] . '</div>';
                }
                $inner = preg_replace('#(<h3>.*?</h3>\s*<ul>.*?</ul>)+#is', '', $inner);
                $inner .= '<div class="kw-cols">' . $cols . '</div>';
            }
            return $m[1] . $inner . $m[3];
        },
        $html
    );

    // 2. Wrap theme sections (Amour/Travail/Finances/Guidance) in .theme-grid
    $themePattern = "#(<section[^>]*>\\s*<h2[^>]*>[^<]*(?:et\\s+l['\x{2019}]amour|et\\s+le\\s+travail|et\\s+les\\s+finances|et\\s+la\\s+guidance)[^<]*</h2>[\\s\\S]*?</section>\\s*)+#iu";
    $html = preg_replace_callback(
        $themePattern,
        function ($m) {
            return '<div class="theme-grid">' . $m[0] . '</div>';
        },
        $html
    );

    return $html;
}

// ==========================================================
// ROUTE: CARD — immersive detail
// ==========================================================
function page_card(PDO $pdo, string $cardId, string $basePath): void {
    $stmt = $pdo->prepare("SELECT c.*, f.name as family_name, f.title_full as family_title,
                                  f.accent, f.element, f.element_sym, f.element_line
                           FROM cards c
                           LEFT JOIN families f ON c.family_key = f.key
                           WHERE c.id = ?");
    $stmt->execute([$cardId]);
    $card = $stmt->fetch();

    if (!$card) {
        http_response_code(404);
        echo '<h1>404 — Carte introuvable</h1>';
        return;
    }

    // Get ES data
    $esStmt = $pdo->prepare("SELECT * FROM card_es WHERE card_id = ?");
    $esStmt->execute([$cardId]);
    $es = $esStmt->fetch();

    // Get global index
    $idxStmt = $pdo->prepare("SELECT COUNT(*) as pos FROM cards WHERE sort_global < ?");
    $idxStmt->execute([$card['sort_global']]);
    $globalIdx = (int)$idxStmt->fetch()['pos'];

    // Get family cards for thumbnails
    $famStmt = $pdo->prepare("SELECT id, family_key, name, num FROM cards WHERE family_key = ? ORDER BY sort_global ASC");
    $famStmt->execute([$card['family_key']]);
    $famCards = $famStmt->fetchAll();
    $inFam = 0;
    foreach ($famCards as $i => $fc) {
        if ($fc['id'] === $cardId) { $inFam = $i; break; }
    }

    // Prev/next cards (global loop)
    $totalCards = (int)$pdo->query("SELECT COUNT(*) FROM cards")->fetchColumn();
    $prevIdx = ($globalIdx - 1 + $totalCards) % $totalCards;
    $nextIdx = ($globalIdx + 1) % $totalCards;
    $prevStmt = $pdo->prepare("SELECT id, name FROM cards ORDER BY sort_global ASC LIMIT 1 OFFSET ?");
    $prevStmt->execute([$prevIdx]);
    $prevCard = $prevStmt->fetch();
    $nextStmt = $pdo->prepare("SELECT id, name FROM cards ORDER BY sort_global ASC LIMIT 1 OFFSET ?");
    $nextStmt->execute([$nextIdx]);
    $nextCard = $nextStmt->fetch();

    // Build URLs
    $imgUrl = "{$basePath}/img/{$card['family_key']}/{$card['id']}.jpg";
    $name = htmlspecialchars($card['name']);
    $accent = htmlspecialchars($card['accent']);
    $familyName = htmlspecialchars($card['family_name']);
    $element = htmlspecialchars($card['element']);
    $html = restructure_html($card['html'] ?? '<p>Pas de description disponible.</p>');
    $associationsHtml = render_associations($cardId, $pdo, $basePath);
    $globalNum = str_pad((string)($globalIdx + 1), 2, '0', STR_PAD_LEFT);
    $inFamNum = $inFam + 1;
    $famCount = count($famCards);

    // ES badges
    $esHtml = '';
    if ($es) {
        $aff = $es['affirmation'] ?? '';
        $rep = $es['reponse'] ?? '';
        if ($aff) $esHtml .= '<span class="es-badge aff">« ' . htmlspecialchars($aff) . ' »</span>';
        if ($rep) $esHtml .= '<span class="es-badge resp"><span class="lbl">Réponse</span> ' . htmlspecialchars($rep) . '</span>';
        if ($esHtml) $esHtml = '<div class="es-badges">' . $esHtml . '</div>';
    }

    // Card of the Day section
    $cardOfDayHtml = '';
    if (!empty($card['card_of_day'])) {
        $cardOfDayHtml = <<<HTML
<div class="card-of-day">
  <div class="card-of-day-label">
    <span class="icon">☀</span>
    <span>Carte du Jour</span>
  </div>
  <div class="card-of-day-content">
    <p>{$card['card_of_day']}</p>
  </div>
</div>
HTML;
    }

    // Thumbnails
    $thumbsHtml = '';
    foreach ($famCards as $fc) {
        $tImgUrl = "{$basePath}/img/{$fc['family_key']}/{$fc['id']}.jpg";
        $tUrl = "{$basePath}/card/{$fc['id']}";
        $tName = htmlspecialchars($fc['name']);
        $current = ($fc['id'] === $cardId) ? ' current' : '';
        $thumbsHtml .= <<<HTML
<a class="d-thumb{$current}" href="{$tUrl}"><img src="{$tImgUrl}" alt="{$tName}" loading="lazy"></a>
HTML;
    }

    // Loop bar
    $prevUrl = "{$basePath}/card/{$prevCard['id']}";
    $nextUrl = "{$basePath}/card/{$nextCard['id']}";
    $prevName = htmlspecialchars($prevCard['name']);
    $nextName = htmlspecialchars($nextCard['name']);

    $extraStyle = "<style>:root{--ac:{$accent}}</style>";

    echo layout_head($basePath, $name . ' — Tarot Divinatoire', $extraStyle);
    echo <<<HTML
<a class="back" href="{$basePath}/">
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
  Retour
</a>
<div class="d-loop">
  <a href="{$prevUrl}">← {$prevName}</a>
  <span class="pos"><b>{$globalNum}</b> / {$totalCards}</span>
  <a href="{$nextUrl}">{$nextName} →</a>
</div>
<div class="d-stage">
  <div class="d-hero">
    <img class="d-hero-img" src="{$imgUrl}" alt="{$name}">
  </div>
  <div class="d-panel">
    <div class="d-panel-inner">
      <div class="d-meta">
        <b>{$globalNum} / {$totalCards}</b>
        <span class="sep">·</span>
        <span>{$familyName} {$inFamNum}/{$famCount}</span>
        <span class="sep">·</span>
        <span>{$element}</span>
      </div>
       <h1 class="d-title"><em>{$name}</em></h1>
      {$esHtml}
      {$cardOfDayHtml}
      <div class="prose">
        {$html}
      </div>
      {$associationsHtml}
      <div class="d-thumbs">
        {$thumbsHtml}
      </div>
    </div>
  </div>
</div>
<script>
const PREV_URL="{$prevUrl}", NEXT_URL="{$nextUrl}";
(function(){
  window.scrollTo(0,0);
  var stage=document.querySelector('.d-stage');if(stage)stage.scrollTop=0;
  var cur=document.querySelector('.d-thumb.current');
  var thumbs=cur&&cur.parentElement;
  if(thumbs)thumbs.scrollLeft=cur.offsetLeft-(thumbs.clientWidth-cur.offsetWidth)/2;
})();
document.addEventListener('keydown',function(e){
  if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA')return;
  if(e.key==='Escape'){window.location.href="{$basePath}/";e.preventDefault();}
  if(e.key==='ArrowLeft'){window.location.href=PREV_URL;e.preventDefault();}
  if(e.key==='ArrowRight'){window.location.href=NEXT_URL;e.preventDefault();}
});
</script>
HTML;
    echo layout_search($pdo, $basePath);
    echo '</body></html>';
}

function normalize_card_name(string $s): string {
    $s = trim($s);
    $s = str_replace(["\u{2018}", "\u{2019}"], "'", $s);
    return mb_strtolower($s, 'UTF-8');
}

function build_card_lookup(PDO $pdo): array {
    static $lookup = null;
    if ($lookup !== null) return $lookup;
    $rows = $pdo->query("SELECT id, family_key, name FROM cards")->fetchAll();
    $lookup = [];
    foreach ($rows as $r) {
        $lookup[normalize_card_name($r['name'])] = $r;
    }
    // Marseille aliases not always in DB name field
    $aliases = [
        "l'arcane sans nom" => 'a_13_Mort',
        'la tour' => 'a_16_Tour',
        'le mat' => 'a_00_Fou',
        'la tempérance' => 'a_14_Temperance',
    ];
    foreach ($aliases as $k => $id) {
        if (!isset($lookup[$k])) {
            foreach ($rows as $r) {
                if ($r['id'] === $id) { $lookup[$k] = $r; break; }
            }
        }
    }
    return $lookup;
}

function match_assoc_card(string $targetName, array $lookup): ?array {
    $candidates = [$targetName];
    if (strpos($targetName, '/') !== false) {
        $parts = array_map('trim', explode('/', $targetName));
        $candidates = array_merge($candidates, $parts);
    }
    foreach ($candidates as $c) {
        $norm = normalize_card_name($c);
        if (isset($lookup[$norm])) return $lookup[$norm];
    }
    return null;
}

function render_associations(string $cardId, PDO $pdo, string $basePath): string {
    static $all = null;
    if ($all === null) {
        // V3 is often deployed alone; prefer a local copy, then use the source corpus in development.
        $sources = [__DIR__ . '/associations.js', __DIR__ . '/../associations.js'];
        $raw = '';
        foreach ($sources as $source) {
            if (is_file($source)) {
                $raw = (string)file_get_contents($source);
                break;
            }
        }
        $json = preg_match('/const\s+CARD_ASSOCIATIONS\s*=\s*(\{.*\})\s*;\s*\nfor/s', $raw, $match) ? $match[1] : '';
        $all = $json ? (json_decode($json, true) ?: []) : [];
    }
    $markdown = $all[$cardId] ?? '';
    if (!$markdown) return '';

    $lookup = build_card_lookup($pdo);

    $sections = [];
    $currentIndex = null;
    foreach (preg_split('/\R/', $markdown) as $line) {
        $line = trim($line);
        if (preg_match('/^##\s+(.+)$/', $line, $match)) {
            $sections[] = ['title' => trim($match[1]), 'items' => []];
            $currentIndex = count($sections) - 1;
        } elseif ($currentIndex !== null && preg_match('/^-\s+\*\*([^*]+)\*\*\s*:\s*(.+)$/', $line, $match)) {
            $pairName = trim($match[1]);
            $desc = trim($match[2]);
            // Extract target card (second part after " + ")
            $target = strpos($pairName, ' + ') !== false ? trim(explode(' + ', $pairName, 2)[1]) : '';
            $card = $target ? match_assoc_card($target, $lookup) : null;
            $sections[$currentIndex]['items'][] = [
                'name' => $pairName,
                'desc' => $desc,
                'card' => $card,
            ];
        }
    }
    $sectionsHtml = '';
    $total = 0;
    foreach ($sections as $section) {
        if (!$section['items']) continue;
        $total += count($section['items']);
        $sectionsHtml .= '<section class="association-section"><h3>' . htmlspecialchars($section['title']) . '</h3><ul>';
        foreach ($section['items'] as $item) {
            $thumb = '';
            if ($item['card']) {
                $c = $item['card'];
                $imgUrl = "{$basePath}/img/{$c['family_key']}/{$c['id']}.jpg";
                $cardUrl = "{$basePath}/card/{$c['id']}";
                $cname = htmlspecialchars($c['name']);
                $thumb = "<a class=\"assoc-thumb\" href=\"{$cardUrl}\"><img src=\"{$imgUrl}\" alt=\"{$cname}\" loading=\"lazy\"></a>";
            } else {
                $thumb = '<span class="assoc-thumb assoc-thumb-empty" aria-hidden="true"></span>';
            }
            // Keep only target label (after " + ") for readability
            $label = strpos($item['name'], ' + ') !== false ? trim(explode(' + ', $item['name'], 2)[1]) : $item['name'];
            $sectionsHtml .= '<li>' . $thumb . '<div class="assoc-text"><a class="assoc-link" href="'
                . ($item['card'] ? "{$basePath}/card/{$item['card']['id']}" : '#') . '">'
                . htmlspecialchars($label) . '</a><p>' . htmlspecialchars($item['desc']) . '</p></div></li>';
        }
        $sectionsHtml .= '</ul></section>';
    }
    if (!$sectionsHtml) return '';
    return '<section class="associations"><h2>Associations</h2><p class="association-intro">' . $total . ' combinaisons avec cette lame</p>' . $sectionsHtml . '</section>';
}

// ==========================================================
// ROUTE: SEARCH API
// ==========================================================
function api_search(PDO $pdo, string $basePath): void {
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-cache');

    $q = trim($_GET['q'] ?? '');
    if (mb_strlen($q) < 1) {
        echo '[]';
        return;
    }

    $like = '%' . $q . '%';
    $stmt = $pdo->prepare("
        SELECT id, family_key AS fk, name, num
        FROM cards
        WHERE name LIKE ? OR md LIKE ?
        ORDER BY
          CASE WHEN name LIKE ? THEN 0 ELSE 1 END,
          sort_global ASC
        LIMIT 20
    ");
    $stmt->execute([$like, $like, $like . '%']);
    $results = $stmt->fetchAll();

    $out = array_map(function ($c) {
        return [
            'id'   => $c['id'],
            'fk'   => $c['fk'],
            'name' => $c['name'],
            'num'  => str_pad((string)(int)$c['num'], 2, '0', STR_PAD_LEFT),
        ];
    }, $results);

    echo json_encode($out, JSON_UNESCAPED_UNICODE);
    exit;
}

// ==========================================================
// ROUTE: IMAGE
// ==========================================================
function serve_image(string $imagePath, PDO $pdo): void {
    // Format: {family_key}/{card_id} or {family_key}/{card_id}.jpg
    $parts = explode('/', $imagePath);
    if (count($parts) !== 2) {
        http_response_code(400);
        echo 'Bad image path';
        return;
    }

    $familyKey = $parts[0];
    $cardId = pathinfo($parts[1], PATHINFO_FILENAME);

    $stmt = $pdo->prepare("SELECT img FROM cards WHERE family_key = ? AND id = ?");
    $stmt->execute([$familyKey, $cardId]);
    $result = $stmt->fetch();

    if (!$result || !$result['img']) {
        http_response_code(404);
        echo 'Image not found';
        return;
    }

    $data = $result['img'];
    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime = $finfo->buffer($data) ?: 'image/jpeg';

    header("Content-Type: {$mime}");
    header('Content-Length: ' . strlen($data));
    header('Cache-Control: public, max-age=31536000, immutable');
    echo $data;
    exit;
}

// ==========================================================
// ROUTE: ICON
// ==========================================================
function serve_icon(): void {
    $path = __DIR__ . '/icon.png';
    if (!file_exists($path)) {
        http_response_code(404);
        echo 'Icon not found';
        return;
    }
    header('Content-Type: image/png');
    header('Content-Length: ' . filesize($path));
    header('Cache-Control: public, max-age=86400');
    readfile($path);
    exit;
}
